class Solution:
    def minDays(self, grid: list[list[int]]) -> int:
        def count_islands(g):
            m, n = len(g), len(g[0])
            visited = [[False] * n for _ in range(m)]
            count = 0
            def dfs(r, c):
                if r < 0 or r >= m or c < 0 or c >= n or visited[r][c] or g[r][c] == 0:
                    return
                visited[r][c] = True
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    dfs(r+dr, c+dc)
            for i in range(m):
                for j in range(n):
                    if g[i][j] == 1 and not visited[i][j]:
                        dfs(i, j)
                        count += 1
            return count

        import sys
        sys.setrecursionlimit(10000)

        if count_islands(grid) != 1:
            return 0

        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    if count_islands(grid) != 1:
                        return 1
                    grid[i][j] = 1
        return 2

