var minDays = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    // Count islands using DFS
    const countIslands = (g) => {
        const visited = Array(m)
            .fill(null)
            .map(() => new Array(n).fill(false));
        let count = 0;
        const dfs = (r, c) => {
            if (r < 0 || r >= m || c < 0 || c >= n || visited[r][c] || g[r][c] === 0) return;
            visited[r][c] = true;
            dfs(r + 1, c);
            dfs(r - 1, c);
            dfs(r, c + 1);
            dfs(r, c - 1);
        };
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (g[i][j] === 1 && !visited[i][j]) {
                    dfs(i, j);
                    count++;
                }
            }
        }
        return count;
    };

    // Already disconnected (0 or 2+ islands)?
    if (countIslands(grid) !== 1) return 0;

    // Try removing each land cell
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                if (countIslands(grid) !== 1) return 1;
                grid[i][j] = 1; // restore
            }
        }
    }

    // Any connected island can always be disconnected in 2 moves
    return 2;
};
